#include <string>
#include <vector>

using namespace std;

class Solution {
public:
    bool isAnagram(string s, string t) {
        if (s.length() != t.length()) {
            return false;
        }
        vector<int> counts(26, 0);
        for (char c : s) {
            counts[c - 'a']++;
        }
        for (char c : t) {
            if (--counts[c - 'a'] < 0) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) {
            counts[s.charAt(i) - 'a']++;
        }
        for (int i = 0; i < t.length(); i++) {
            if (--counts[t.charAt(i) - 'a'] < 0) {
                return false;
            }
        }
        return true;
    }
}

/**
 * @param {string} s
 * @param {string} t
 * @return {boolean}
 */
var isAnagram = function(s, t) {
    if (s.length !== t.length) {
        return false;
    }
    const counts = new Array(26).fill(0);
    const codeA = 'a'.charCodeAt(0);
    for (let i = 0; i < s.length; i++) {
        counts[s.charCodeAt(i) - codeA]++;
    }
    for (let i = 0; i < t.length; i++) {
        const idx = t.charCodeAt(i) - codeA;
        counts[idx]--;
        if (counts[idx] < 0) {
            return false;
        }
    }
    return true;
};
